-- Check: every table should report the row count shown in data/excel/NorthbridgeLending.xlsx (README sheet).
SELECT 'Branch' AS TableName, COUNT(*) AS RowsLoaded FROM dbo.Branch
UNION ALL SELECT 'LoanOfficer', COUNT(*) FROM dbo.LoanOfficer
UNION ALL SELECT 'Product', COUNT(*) FROM dbo.Product
UNION ALL SELECT 'Customer', COUNT(*) FROM dbo.Customer
UNION ALL SELECT 'Loan', COUNT(*) FROM dbo.Loan
UNION ALL SELECT 'Payment', COUNT(*) FROM dbo.Payment
UNION ALL SELECT 'Collateral', COUNT(*) FROM dbo.Collateral
UNION ALL SELECT 'CreditRating', COUNT(*) FROM dbo.CreditRating;
